(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  for (let k = 0; k < 300 && !(window.__luminati && window.__luminati.loadMs); k++) await sleep(100);
  const g = window.__game.game;
  const failed = [];
  const PS = window.PS = {
    sleep, g, failed,
    expect: (ok, label) => {
      if (ok) return true;
      failed.push(label);
      setTimeout(() => { throw new Error('party.story: ' + label); });
      return false;
    },
    /** until fn() holds (polled every 50 ms, at most ms) */
    until: async (fn, ms = 10000) => { const t0 = performance.now(); while (!fn() && performance.now() - t0 < ms) await sleep(50); return !!fn(); },
    /** no run, no conversation, no dialog */
    idle: () => PS.until(() => !g.story.run && !g.busy && !g.ui.dialog.isOpen && !g.story.queue.length),
    member: () => window.__game.party.info()?.members?.[0] ?? null,
    villager: () => g.npcById.get('sela'),
    rock: () => g.level.objects.find((o) => o.id === 'with-sela'),
  };
  const { expect } = PS;
  expect(g.story && g.party === null && window.__game.party.info() === null && !('party' in window.__game.state()), 'before a join: a story, no party, no state().party');
  expect(!g.story.present(PS.rock()), 'before: the rock with when: party:sela is away');
  // a refused join makes no party (PARTY.md §10: nothing of the party on a level nobody joins)
  await window.__game.story.run(['party join ghost', 'party join pip-the-ghost']);
  expect(g.party === null && window.__game.party.info() === null && !('party' in window.__game.state()) && !g.engine.input.bindings.party && !document.querySelector('.lu-party, .lu-pframes'),
    'a refused party join makes no party (no state().party, no G binding, no party DOM)');
  // a talk script's choice: party join (auto answers the first option)
  window.__game.story.auto([0]);
  expect(window.__game.talkTo('sela'), 'talkTo sela');
  await sleep(200);
  await PS.idle();
  const m = PS.member();
  expect(m && m.id === 'sela' && m.cls === 'warden' && m.preset === 'balanced', 'party join sela as warden balanced: ' + JSON.stringify(m));
  expect(window.__game.story.holds('party:sela') && window.__game.story.holds('party = 1') && !window.__game.story.holds('party:pip'), 'conditions: party:sela, party = 1');
  expect(PS.villager().present === false, 'the villager is hidden while she is in the party');
  expect(g.story.present(PS.rock()), 'the rock with when: party:sela is there now');
  g.teleport(9, 10.5);
  g.rig.snap();
  return JSON.stringify({ member: m, errors: g.story.errors, failed });
})()

