(async () => {
  const { g, expect, failed, until, sleep } = window.PS;
  // (the party UI package's tactics panel when it is there; else a stand-in with its interface)
  if (!g.ui.party) {
    const panel = { isOpen: false, opened: null, onRule: null, onClose: null, onSound: null,
      open(o) { this.isOpen = true; this.opened = o; }, close() { if (this.isOpen) { this.isOpen = false; this.onClose?.(); } },
      update() { return false; }, setRule() {}, dispose() {} };
    g.ui.party = { panel, frames: { update() {}, setVisible() {}, dispose() {} } };
    window.PS.standIn = true;
  }
  window.__game.story.auto(false);
  const run = window.__game.story.run(['party menu sela', 'set menu-closed']);
  const opened = await until(() => g.party.menuOpen, 5000);
  await sleep(500);
  expect(opened && window.__game.story.get('menu-closed') === 0 && !!g.story.run, 'party menu: the panel opens, the run waits');
  const info = window.__game.party.info();
  g.party.closeMenu();
  await run;
  expect(window.__game.story.get('menu-closed') === 1 && !g.party.menuOpen, 'party menu: the run goes on once the panel closed');
  return JSON.stringify({ menuOpen: info.menuOpen, standIn: !!window.PS.standIn, failed });
})()

(async () => {
  const { g, expect, failed, until, sleep } = window.PS;
  // the tactics panel open (G, not a script): a queued run and a background run wait until it closes
  const opened = window.__game.party.menu(true);
  await sleep(300);
  window.__game.story.set('ring');
  await sleep(1000);
  const s = window.__game.story;
  expect(opened && g.partyMenuOpen && !g.story.run && g.story.queue.length === 1 && s.get('rang') === 0 && s.get('bg-rang') === 0 && !g.ui.dialog.isOpen,
    'the tactics panel open: the story waits (no run, no background run, no window): ' + JSON.stringify({ opened, run: !!g.story.run, queue: g.story.queue.length, rang: s.get('rang'), bg: s.get('bg-rang') }));
  s.auto(true);
  window.__game.party.menu(false);
  const ran = await until(() => s.get('rang') === 1 && s.get('bg-rang') === 1, 5000);
  expect(ran, 'the panel closed: both run');
  await PS.idle();
  s.auto(false);
  return JSON.stringify({ opened, ran, failed });
})()

