(async () => {
  const { g, expect, failed, until } = window.PS;
  // (the player read the line: it stays, its options come under it — no page of its own, no retyping)
  const choosing = await until(() => g.ui.dialog.isChoosing, 8000);
  const text = document.querySelector('.lu-dialog__text')?.textContent ?? '';
  const speaker = document.querySelector('.lu-dialog__speaker')?.textContent ?? '';
  const options = [...document.querySelectorAll('.lu-dialog__choices .lu-choice')].map((e) => e.textContent.trim());
  expect(choosing && text === 'Which way now?' && speaker === 'Sela' && options.join() === 'North,South', 'a choice after an if block: on the held line: ' + JSON.stringify({ choosing, text, speaker, options }));
  return JSON.stringify({ text, speaker, options, failed });
})()

